void sc_format_asn1_entry(struct sc_asn1_entry *entry, void *parm, void *arg,
                          int set_present)
{
        entry->parm = parm;
        entry->arg  = arg;
        if (set_present)
                entry->flags |= SC_ASN1_PRESENT;
}

void sc_copy_asn1_entry(const struct sc_asn1_entry *src,
                        struct sc_asn1_entry *dest)
{
        while (src->name != NULL) {
                *dest = *src;
                dest++;
                src++;
        }
        dest->name = NULL;
}

